head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
gBondYn = js_bond_yn;
scwin.gParamObj = new Array(9);
scwin.vScrenID = 'ULDSTF26700.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
    dts_SCHDL_DD.DataID = "/SubmitStatus.do?method=readSubmitSCHDCODE";
    dts_SCHDL_DD.Reset();

    //최근일자를 셋팅
    var toDate = $c.ut.cGetToday("yyyymmdd");
    var sDate = '';
    for (var i = 1; i <= dts_SCHDL_DD.getTotalRow(); i++) {
        sDate = dts_SCHDL_DD.getCellData(i, "VALUE");
        if (parseInt(toDate) > parseInt(dts_SCHDL_DD.getCellData(i, "VALUE"))) {
            sDate = dts_SCHDL_DD.getCellData(i - 1, "VALUE");
            break;
        }
    }
    //alert('[sDate]'+sDate);
    $c.stf.setObjectValue(cmb_SCHDL_DD, sDate);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market == "9") {
        rdo_MKT_ID.setDisabled(false);
        $c.stf.setObjectValue(rdo_MKT_ID, "1");
    } else {
        // 콘트롤 잠그기.
        rdo_MKT_ID.setDisabled(true);
    }
    //alert('[js_dep_cd]'+js_dep_cd + "_" + js_market);

    if (scwin.gDepCd != "ZSYS") {
        $c.stf.showObj(btn_Snd, false);
    }
};
scwin.fn_Search = function() {
    var vMKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
    var vSCHDL_DD = $c.stf.getObjectValue(cmb_SCHDL_DD);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);

    //var vYYYY= getObjectValue(cmb_YYYY);

    if (vMKT_ID == "9" || vMKT_ID == "") {
        $c.win.alert("시장구분을 선택해 주세요");
        return false;
    }
    var url = "/SubmitStatus.do?method=listSubmitStatusNew";
    url += "&MKT_ID=" + vMKT_ID;
    url += "&SCHDL_DD=" + vSCHDL_DD;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&BOND_YN=" + gBondYn;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_read = function(GridID, row, colid) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..	
    //var vIBAS_ACNTCLS_MM = objDataID.NameString(row, "BAS_ACNTCLS_MM");

    if (row < 1) return;
    if (colid == "WRTRPT_KIND_NM") {
        var CMD = "R";
        var vIBAS_YY = objDataID.getCellData(row, "BAS_YY");
        var vIBAS_ACNTCLS_MM = objDataID.getCellData(row, "BAS_ACNTCLS_MM");
        var vIWRTRPT_KIND_CD = objDataID.getCellData(row, "WRTRPT_KIND_CD");
        var vIMKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
        var vIBAS_ACNTCLS_MM_YY = objDataID.getCellData(row, "BAS_ACNTCLS_MM_YY");
        var vIWRTRPT_KIND_CDNM = objDataID.getCellData(row, "WRTRPT_KIND_NM");
        var vIDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
        var vIDEP_CDNM = cmb_DEP_CD.getText();
        var vIWRTRPT_SUBMIT_SCHDL_DD = cmb_SCHDL_DD.getText();
        var url = "/dsclsrch/ULDSTF26701.gfm?";
        url += "&BAS_YY=" + vIBAS_YY;
        url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
        url += "&WRTRPT_KIND_CD=" + vIWRTRPT_KIND_CD;
        url += "&BAS_ACNTCLS_MM_YY=" + vIBAS_ACNTCLS_MM_YY;
        url += "&WRTRPT_KIND_CDNM=" + vIWRTRPT_KIND_CDNM;
        url += "&DEP_CD=" + vIDEP_CD;
        url += "&DEP_CDNM=" + vIDEP_CDNM;
        url += "&MKT_ID=" + vIMKT_ID;
        url += "&WRTRPT_SUBMIT_SCHDL_DD=" + vIWRTRPT_SUBMIT_SCHDL_DD;
        if (scwin.fn_setParam(CMD, vIBAS_YY, vIBAS_ACNTCLS_MM, vIWRTRPT_KIND_CD, vIBAS_ACNTCLS_MM_YY, vIWRTRPT_KIND_CDNM, vIDEP_CDNM, vIMKT_ID, vIWRTRPT_SUBMIT_SCHDL_DD)) // formal arguments

        {
            //frame.CreateDialogFrame("child01", "/dsclsrch/ULDSTF26601.gfm", "상세조회", 10, 10, 810,650, "window");	
            $c.frame.path("../../").GWinOpen("child01", url, "상세조회", 20, 20, 1255, 640 + 40, "");
        }
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.fn_HideDebugCtrls = function() {
    if (js_market != "9") {
        $c.stf.showObj(panel_mkt, false);
    }
};



//금감원 전송대상 내역 팝업창 띄우기
scwin.fn_SubmitObjPopup = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF26702", "/dsclsrch/ULDSTF26702.gfm", "보고서 제출대상 법인목록", 50, 50, 1077, 784, "window");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "제출현황목록", "", "8");
};
scwin.btn_Snd_onclick = function() {
    scwin.fn_SubmitObjPopup();
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_read(grd_Grid, row, colid);
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    scwin.fn_SetCode();
    $c.cm.PanelToGroupBox(panel_1);
};
